for k, v in TYPES.items():
    v["era"] = "dark-ages" if v["built"][0] < 1450 else max((e for e, y in E.ERA_STARTS if y <= v["built"][0]), key=lambda e: dict(E.ERA_STARTS)[e])
    v["eras"] = (["dark-ages"] if v["era"] == "dark-ages" else []) + [e for e, y in E.ERA_STARTS if v["era"] == "dark-ages" or y >= dict(E.ERA_STARTS)[v["era"]]]
    B.TYPES[k] = v

